#!/usr/bin/env python3
"""sessionStart hook: give the agent a short snapshot of the repository state.

Reports branch, pending changes, dev-environment status, which investing.com variables
are configured (names only, never values) and the CSV files available in data/.
"""

from __future__ import annotations

import os
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))

import _hooklib as hl  # noqa: E402

CREDENTIAL_VARS = ("INVESTING_EMAIL", "INVESTING_PASSWORD")


def _git(root: Path, *args: str) -> str:
    code, out = hl.run(["git", *args], root, timeout=5)
    return out if code == 0 else "n/a"


def _configured_credentials(root: Path) -> list[str]:
    """Return the names of credential variables defined in env or .env (values unread)."""
    names = {name for name in CREDENTIAL_VARS if os.environ.get(name)}
    env_file = root / ".env"
    if env_file.is_file():
        for line in env_file.read_text(encoding="utf-8", errors="ignore").splitlines():
            key, sep, value = line.partition("=")
            if sep and key.strip() in CREDENTIAL_VARS and value.strip():
                names.add(key.strip())
    return sorted(names)


def build_context(root: Path) -> str:
    """Compose the context text."""
    changes = [
        line for line in _git(root, "status", "--porcelain").splitlines() if line
    ]
    csv_files = sorted(p.name for p in (root / "data").glob("*.csv"))
    creds = _configured_credentials(root)
    missing = [v for v in CREDENTIAL_VARS if v not in creds]
    dev_env = (root / ".make_cache/.env_dev_tag").exists()
    lines = [
        "PortfolioUtils session context (generated by a hook):",
        f"- Branch: {_git(root, 'rev-parse', '--abbrev-ref', 'HEAD')}; "
        f"last commit: {_git(root, 'log', '-1', '--pretty=%h %s')}",
        f"- Uncommitted changes: {len(changes)} file(s)",
        f"- Dev environment installed (make setup_dev): {'yes' if dev_env else 'no - run make setup_dev'}",
        f"- investing.com credentials configured: {', '.join(creds) or 'none'}"
        + (f" (missing: {', '.join(missing)})" if missing else ""),
        f"- CSV files in data/: {len(csv_files)}"
        + (
            f" ({', '.join(csv_files[:15])}{', ...' if len(csv_files) > 15 else ''})"
            if csv_files
            else ""
        ),
        "- Quality gate: make checks (format, ruff, pydoclint, strict mypy, licensecheck, "
        "pytest with 95% branch coverage). Never read .env or print credentials.",
    ]
    return "\n".join(lines)


def main() -> None:
    """Entry point."""
    try:
        event = hl.read_event()
        hl.emit({"additionalContext": build_context(hl.repo_root(event))})
    except Exception:  # noqa: BLE001 - context is optional, never break the session
        hl.emit({})


if __name__ == "__main__":
    main()
